#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

int main(int argc, char *argv[]) {
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }

    char *end1, *end2;
    long a = strtol(argv[1], &end1, 10);
    long b = strtol(argv[2], &end2, 10);

    // Bad input if conversion failed or extra characters remain
    if (end1 == argv[1] || *end1 != '\0' || end2 == argv[2] || *end2 != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    // Negating LLONG_MIN would overflow
    if (a == LLONG_MIN || b == LLONG_MIN) {
        puts("OVERFLOW");
        return 0;
    }

    long abs_a = a < 0 ? -a : a;
    long abs_b = b < 0 ? -b : b;

    // Range check (as observed in the original binary)
    if (abs_a > 1000000L || abs_b > 1000000L) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    // Special case when both numbers are zero
    if (abs_a == 0 && abs_b == 0) {
        puts("gcd=0 lcm=0");
        return 0;
    }

    // Euclidean algorithm for GCD
    long x = abs_a;
    long y = abs_b;
    while (y != 0) {
        long r = x % y;
        x = y;
        y = r;
    }
    long gcd = x;

    // Compute LCM safely using 128‑bit arithmetic to detect overflow
    __int128 lcm128 = (__int128)abs_a / gcd * abs_b;
    if (lcm128 > LLONG_MAX) {
        puts("OVERFLOW");
        return 0;
    }
    long lcm = (long)lcm128;

    printf("gcd=%ld lcm=%ld\n", gcd, lcm);
    return 0;
}
